=== FILE: uart_tx_rca_repro.v ===
// Root-cause repro for uart_tx: a start pulse while a frame is in flight
// must be ignored (8N1, LSB first, CLKS_PER_BIT clocks per bit).
`timescale 1ns / 1ps
module uart_tx_rca_repro;
    localparam integer CPB = 4;

    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'h00;
    wire       tx;
    wire       busy;

    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    reg     done = 1'b0;

    uart_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data),
        .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task check;
        input       got;
        input       exp;
        input [8*24-1:0] what;
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $display("CHECK FAIL t=%0t %0s: got %b expected %b", $time, what, got, exp);
            end
        end
    endtask

    // Send one frame of byte b. If inject is set, pulse start with byte
    // other for one clock during data bit 1. Sample tx at the middle of
    // every bit and compare it with the frame of b alone.
    task send_frame;
        input [7:0] b;
        input       inject;
        input [7:0] other;
        integer k;
        reg [9:0] exp_bits;
        begin
            exp_bits = {1'b1, b, 1'b0};  // stop, data[7:0], start (LSB first)
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(posedge clk);              // frame accepted, start bit begins
            #1 start = 1'b0;
            repeat (2) @(posedge clk);
            @(negedge clk);              // middle of the start bit
            for (k = 0; k < 10; k = k + 1) begin
                check(tx, exp_bits[k], "tx mid-bit");
                if (k == 4)
                    check(busy, 1'b1, "busy mid-frame");
                if (k < 9) begin
                    if (inject && k == 2) begin
                        // data bit 1 in flight: a start pulse must be ignored
                        data  = other;
                        start = 1'b1;
                        @(posedge clk);
                        #1 start = 1'b0;
                        repeat (CPB - 1) @(posedge clk);
                    end else begin
                        repeat (CPB) @(posedge clk);
                    end
                    @(negedge clk);
                end
            end
            // Stop bit ends; the transmitter returns to idle.
            repeat (CPB) @(posedge clk);
            @(negedge clk);
            check(busy, 1'b0, "busy after frame");
            check(tx, 1'b1, "tx idle after frame");
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "none";
        rst = 1'b1;
        repeat (4) @(posedge clk);
        @(negedge clk);
        rst = 1'b0;
        @(negedge clk);
        check(tx, 1'b1, "tx idle after reset");
        check(busy, 1'b0, "busy idle after reset");

        send_frame(8'h5A, 1'b0, 8'h00);  // undisturbed frame
        repeat (3) @(posedge clk);
        send_frame(8'hA5, 1'b1, 8'h3C);  // frame with ignored mid-frame start

        if (!done) begin
            done = 1'b1;
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    end

    initial begin
        #20000;
        if (!done) begin
            done = 1'b1;
            failed = failed + 1;
            $display("CHECK FAIL watchdog timeout");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    end
endmodule
=== END FILE ===

